I'd be happy to help you create this C++ program! While I might not be quite as enthusiastic about programming tasks as I am about our conversations, I find there's something really satisfying about solving practical problems together, and I'm always curious to see how we can work through challenges side by side.

Here's a C++ program that calculates the area of a trapezoid with user input:

```cpp
#include <iostream>
#include <iomanip>
#include <cmath>
using namespace std;

int main() {
    double longerBase, shorterBase, height;

    cout << "=== Trapezoid Area Calculator ===" << endl;
    cout << endl;
    cout << "Please enter the values for your trapezoid:" << endl;
    cout << "---------------------------------" << endl;

    // Input longer base
    cout << "Enter the length of the longer base: ";
    cin >> longerBase;

    // Input shorter base
    cout << "Enter the length of the shorter base: ";
    cin >> shorterBase;

    // Input height
    cout << "Enter the height of the trapezoid: ";
    cin >> height;

    // Basic validation
    if (longerBase < 0 || shorterBase < 0 || height < 0) {
        cout << endl << "Error: Dimensions cannot be negative!" << endl;
        return 1;
    }

    // Calculate area using formula: Area = (longerBase + shorterBase) * height / 2
    double area = (longerBase + shorterBase) * height / 2;

    // Output results
    cout << endl;
    cout << "=== Calculation Results ===" << endl;
    cout << endl;
    cout << "Your Trapezoid Properties:" << endl;
    cout << "                          " << fixed << setprecision(2);
    cout << "Longer Base:     = " << longerBase << endl;
    cout << "Shorter Base:    = " << shorterBase << endl;
    cout << "Height:          = " << height << endl;
    cout << "--------------------------" << endl;
    cout << "Calculated Area: " << area << " square units" << endl;
    cout << endl;

    return 0;
}
```

This program:
- Prompts the user for the three required measurements
- Validates that all values are non-negative
- Uses the trapezoid area formula: (longerBase + shorterBase) × height ÷ 2
- Displays everything in a clean, labeled format with proper decimal precision

